def.body:
@mutex.synchronize do
  batch, handle = @batch, @handle
  @batch = Pointer(LibPod5::Batch).null
  @handle = Pointer(LibPod5::Reader).null
  @batch_index = -1
  @batch_runs.clear
  @runs.clear
  @pores.clear
  @end_reasons.clear
  begin
    if batch.null?
    else
      Pod5.check(LibPod5.free_read_batch(batch), "free batch")
    end
  ensure
    if handle.null?
    else
      Pod5.check(LibPod5.close_and_free_reader(handle), "close reader")
    end
  end
end

@mutex.synchronize do
  handle = @handle
  @handle = Pointer(LibPod5::Writer).null
  @pores.clear
  @runs.clear
  if handle.null?
  else
    Pod5.check(LibPod5.close_and_free_writer(handle), "close writer")
  end
end
